CREATE TABLE _smrt_contexts(id VARCHAR PRIMARY KEY, owner_class VARCHAR NOT NULL, owner_id VARCHAR NOT NULL, "scope" VARCHAR NOT NULL, "key" VARCHAR NOT NULL, "value" VARCHAR, metadata VARCHAR, "version" INTEGER DEFAULT(1), confidence FLOAT DEFAULT(1.0), success_count INTEGER DEFAULT(0), failure_count INTEGER DEFAULT(0), created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP), updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP), last_used_at TIMESTAMP, expires_at TIMESTAMP, UNIQUE(owner_class, owner_id, "scope", "key", "version"));